import express from 'express';

const app = express();
app.use(express.json());

const notes = [];
let nextId = 1;

function validate(body) {
  const { text } = body ?? {};
  if (typeof text !== 'string' || text.trim() === '') return 'text is required';
  return null;
}

app.get('/api/notes', (req, res) => res.json(notes));

app.get('/api/notes/:id', (req, res) => {
  const note = notes.find((n) => n.id === Number(req.params.id));
  if (!note) return res.status(404).json({ error: 'Note not found' });
  res.json(note);
});

app.post('/api/notes', (req, res) => {
  const problem = validate(req.body);
  if (problem) return res.status(400).json({ error: problem });
  const note = { id: nextId++, text: req.body.text.trim(), done: false };
  notes.push(note);
  res.status(201).json(note);
});

app.put('/api/notes/:id', (req, res) => {
  const note = notes.find((n) => n.id === Number(req.params.id));
  if (!note) return res.status(404).json({ error: 'Note not found' });
  const problem = validate(req.body);
  if (problem) return res.status(400).json({ error: problem });
  note.text = req.body.text.trim();
  note.done = req.body.done === true;
  res.json(note);
});

app.delete('/api/notes/:id', (req, res) => {
  const index = notes.findIndex((n) => n.id === Number(req.params.id));
  if (index === -1) return res.status(404).json({ error: 'Note not found' });
  notes.splice(index, 1);
  res.status(204).end();
});

app.use((req, res) => res.status(404).json({ error: `No route for ${req.method} ${req.originalUrl}` }));

app.use((err, req, res, next) => {
  if (err.type === 'entity.parse.failed') return res.status(400).json({ error: 'Invalid JSON body' });
  console.error(err);
  res.status(500).json({ error: 'Internal server error' });
});

app.listen(3000, () => console.log('Notes API on http://localhost:3000'));

