import { setTimeout as sleep } from 'node:timers/promises';

export async function fetchJson(url, { retries = 3, timeoutMs = 5000 } = {}) {
  for (let attempt = 1; attempt <= retries; attempt++) {
    try {
      const response = await fetch(url, { signal: AbortSignal.timeout(timeoutMs) });
      if (response.status >= 500) throw new Error(`Server error ${response.status}`);
      if (!response.ok) {
        const error = new Error(`Request failed with ${response.status}`);
        error.permanent = true; // 4xx will not get better by retrying
        throw error;
      }
      return await response.json();
    } catch (error) {
      if (error.permanent || attempt === retries) throw error;
      const delay = 200 * 2 ** (attempt - 1);
      console.warn(`Attempt ${attempt} failed (${error.name}: ${error.message}); retrying in ${delay} ms`);
      await sleep(delay);
    }
  }
}

const books = await fetchJson('http://localhost:3000/api/books', { retries: 3, timeoutMs: 2000 });
console.log(`Fetched ${books.length} books`);

import { DatabaseSync } from 'node:sqlite';

const db = new DatabaseSync('todos.db');

db.exec(`
  CREATE TABLE IF NOT EXISTS todos (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    text TEXT NOT NULL,
    done INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )
`);

const statements = {
  insert: db.prepare('INSERT INTO todos (text) VALUES (?)'),
  list: db.prepare('SELECT id, text, done FROM todos ORDER BY id'),
  complete: db.prepare('UPDATE todos SET done = 1 WHERE id = ?'),
  remove: db.prepare('DELETE FROM todos WHERE id = ?'),
};

export function addTodo(text) {
  return statements.insert.run(text).lastInsertRowid;
}

export function listTodos() {
  return statements.list.all().map((row) => ({ ...row, done: row.done === 1 }));
}

export function completeTodo(id) {
  return statements.complete.run(id).changes === 1;
}

export function removeTodo(id) {
  return statements.remove.run(id).changes === 1;
}

const id = addTodo('Write the README');
completeTodo(id);
for (const todo of listTodos()) {
  console.log(todo.done ? '[x]' : '[ ]', todo.id, todo.text);
}

import { test, after } from 'node:test';
import assert from 'node:assert/strict';
import { createServer } from 'node:http';
import { once } from 'node:events';

function handler(req, res) {
  if (req.url === '/health') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    return res.end('{"status":"ok"}');
  }
  res.writeHead(404, { 'Content-Type': 'text/plain' });
  res.end('Not found');
}

const server = createServer(handler).listen(0);
await once(server, 'listening');
const base = `http://localhost:${server.address().port}`;

after(() => server.close());

test('GET /health reports ok', async () => {
  const response = await fetch(`${base}/health`);
  assert.equal(response.status, 200);
  assert.deepEqual(await response.json(), { status: 'ok' });
});

test('unknown paths return 404', async () => {
  const response = await fetch(`${base}/nope`);
  assert.equal(response.status, 404);
  assert.equal(await response.text(), 'Not found');
});

import express from 'express';

const app = express();
app.set('trust proxy', 1);

app.get('/health', (req, res) => {
  res.json({ status: 'ok', uptime: Math.round(process.uptime()) });
});

const port = Number(process.env.PORT ?? 3000);
const server = app.listen(port, () => console.log(`Listening on port ${port}`));

let shuttingDown = false;

function shutdown(signal) {
  if (shuttingDown) return;
  shuttingDown = true;
  console.log(`${signal} received, draining connections`);
  server.close((error) => {
    if (error) console.error(error);
    process.exit(error ? 1 : 0);
  });
  setTimeout(() => {
    console.error('Forcing exit after 10 s');
    process.exit(1);
  }, 10_000).unref();
}

for (const signal of ['SIGTERM', 'SIGINT']) {
  process.on(signal, () => shutdown(signal));
}
